92	\title{Probing TeV scale Top-Philic Resonances with Boosted Top-Tagging at the High Luminosity LHC}
93	
94	\author{Jeong Han Kim} \email{jeonghan.kim@kaist.ac.kr} 
95	\affiliation{Department of Physics, Korea Advanced Institute of Science and Technology, 335 Gwahak-ro, Yuseong-gu, Daejeon 305-701, Korea, and Center for Theoretical Physics of the Universe, Institute for Basic Science (IBS), Daejeon 34051, Republic of Korea}
